  const [password, setPassword] = useState('');
  const [remember, setRemember] = useState(false);

  return (
    <main
      style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: 'var(--g-color-base-background)',
      }}
