        <Flex direction=\"column\" gap=\"spacing-4\" style={{padding: 'var(--g-spacing-6)'}}>
          <Text variant=\"header-1\">Вход</Text>

          <TextInput
            type=\"email\"
            size=\"l\"
            placeholder=\"Email\"
            value={email}
            onUpdate={setEmail}
          />

          <PasswordInput
            size=\"l\"
            placeholder=\"Пароль\"
            value={password}
            onUpdate={setPassword}
          />

          <Checkbox
            size=\"l\"
            checked={remember}
            onUpdate={setRemember}
          >
            Запомнить меня
          </Checkbox>

          <Button view=\"action\" size=\"l\" width=\"max\">
            Войти
          </Button>
        </Flex>
      </Card>
    </main>
  );
}
EOF"

